    public static int trSortedMedian(emon.Port.Cells a, int n) {
        // Sort a[0..n) in place (insertion) and answer its upper median a[n / 2]; 0 for none.
        int i = 1;
        int j = 0;
        int v = 0;
        if (n <= 0) {
            return 0;
        }
        while (i < n) {
            j = i;
            while ((j > 0) && (emon.Port.cellsAt(a, j - 1) > emon.Port.cellsAt(a, j))) {
                v = emon.Port.cellsAt(a, j);
                emon.Port.cellsSet(a, j, emon.Port.cellsAt(a, j - 1));
                emon.Port.cellsSet(a, j - 1, v);
                j -= 1;
            }
            i += 1;
        }
        return emon.Port.cellsAt(a, n / 2);
    }
